/**
 * Client-safe access to the hosted request context.
 *
 * The real context lives in an AsyncLocalStorage inside
 * `adapters/fs/veryfront/request-context.ts`, whose module-scope
 * `node:async_hooks` import must stay out of browser bundles. Shared
 * client/server code (the config loader's hosted-identity assertions) reads
 * the context through this holder instead: the server module registers its
 * accessor when it loads, and in the browser nothing ever registers, so
 * `currentRequestContext()` returns null — the correct answer there, since a
 * hosted request context only exists while the server VFS adapter runs a
 * request.
 *
 * Registration cannot be observed "too early": the only writer of the
 * context (`multi-project-adapter.ts`'s `asyncLocalStorage.run`) imports the
 * server module, so any populated context implies the accessor is in place.
 */
let accessor;
/** Called by the server request-context module when it loads. */
export function registerRequestContextAccessor(fn) {
    if (accessor !== undefined && accessor !== fn) {
        throw new TypeError("The hosted request context accessor is already registered");
    }
    accessor = fn;
}
/** The current hosted request context, or null outside a server request. */
export function currentRequestContext() {
    return accessor?.() ?? null;
}
let fileCacheIsolation;
/** Called by the server request-context module when it loads. */
export function registerRequestScopedFileCacheIsolation(fn) {
    if (fileCacheIsolation !== undefined && fileCacheIsolation !== fn) {
        throw new TypeError("The hosted request file-cache isolation is already registered");
    }
    fileCacheIsolation = fn;
}
/**
 * Run an operation in the current hosted request context without that
 * request's file cache. Use it for work whose result other requests share, so
 * bytes one request pinned earlier cannot reach requests that never saw them.
 */
export function runWithoutRequestScopedFileCache(fn) {
    return fileCacheIsolation === undefined ? fn() : fileCacheIsolation(fn);
}
let runtimeAccessor;
/** @internal Register the server execution identity for public contextual clients. */
export function registerRuntimeRequestContextAccessor(fn) {
    if (runtimeAccessor !== undefined && runtimeAccessor !== fn) {
        throw new TypeError("The runtime request context accessor is already registered");
    }
    runtimeAccessor = fn;
}
/** Consuming identity for service clients, falling back to ordinary hosted requests. */
export function currentRuntimeRequestContext() {
    return runtimeAccessor?.() ?? currentRequestContext();
}
